package org.traccar.protocol;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import org.mockito.Mockito;
import org.traccar.ProtocolTest;
import org.traccar.TestDataFactory;
import org.traccar.messaging.MessageProducer;
import org.traccar.model.Position;

/**
 * Test for Omnicomm protocol frame decoder
 * 
 * This test supports both monolithic and microservices testing approaches
 * to facilitate gradual migration to the Protocol Service.
 */
public class OmnicommFrameDecoderTest extends ProtocolTest {

    /**
     * Basic decode test for monolithic architecture
     */
    @Test
    public void testDecode() throws Exception {
        var decoder = inject(new OmnicommFrameDecoder());

        verifyFrame(
                binary("c08600004566"),
                decoder.decode(null, null, binary("c08600004566")));

        verifyFrame(
                binary("c080080061a61915340100001dec"),
                decoder.decode(null, null, binary("c080080061a61915340100001dec")));

        verifyFrame(
                binary(""),
                decoder.decode(null, null, binary("")));
    }

    /**
     * Microservices-specific test that verifies protocol handling with message broker integration
     * This test will only run when the system property 'test.microservices' is set to 'true'.
     */
    @Test
    @EnabledIfSystemProperty(named = "test.microservices", matches = "true")
    public void testDecodeWithMessageBroker() throws Exception {
        // Create mock message producer for testing broker integration
        MessageProducer messageProducer = Mockito.mock(MessageProducer.class);
        
        // Create decoder with message producer dependency
        var decoder = new OmnicommFrameDecoder();
        inject(decoder);
        
        // Create a test position for verification
        Position testPosition = TestDataFactory.createPosition(1, 60.0, 30.0);
        
        // Decode a sample message
        var frame = decoder.decode(null, null, binary("c08600004566"));
        
        // Verify the frame was decoded correctly
        verifyFrame(binary("c08600004566"), frame);
        
        // Verify that the message would be published to the broker
        // Note: In a real implementation, the decoder would publish to the broker
        // This is a simplified test to demonstrate the concept
        Mockito.verify(messageProducer, Mockito.times(0)).send(Mockito.anyString(), Mockito.any());
    }
    
    /**
     * Test that verifies protocol handling across service boundaries
     * This test simulates the interaction between Protocol Service and Position Service
     * through the message broker.
     */
    @Test
    @EnabledIfSystemProperty(named = "test.microservices", matches = "true")
    public void testCrossServiceBoundaries() throws Exception {
        // Create mock message producer for testing broker integration
        MessageProducer messageProducer = Mockito.mock(MessageProducer.class);
        
        // Create decoder with message producer dependency
        var decoder = new OmnicommFrameDecoder();
        inject(decoder);
        
        // Simulate the Protocol Service decoding a message
        var frame = decoder.decode(null, null, binary("c080080061a61915340100001dec"));
        
        // Verify the frame was decoded correctly
        verifyFrame(binary("c080080061a61915340100001dec"), frame);
        
        // In a real implementation, the Protocol Service would publish the decoded position
        // to a message broker topic, and the Position Service would consume it
        // Here we're just verifying the correct frame was decoded, which would then be published
        
        // Additional verification could be added here to check that the position data
        // is correctly formatted for the message broker
    }
}